style.css:
@-moz-document domain("www.nitrotype.com") {
/* This theme was made by DuckyFul, Discord: duckyful , Youtube: DuckyFul */
body {
background:none
}

html {
background:fixed url(https://images.hdqwalls.com/download/neon-world-7o-2560x1440.jpg),#3e3c40;
background-size:100%
}

.logo-SVGcontainer {
display:block;
height:0;
padding:0;
padding-bottom:14%;
position:relative;
width:100%;
opacity:95%
}

.bg--gradient {
background:fixed
}

.card--grit {
background:none
}

.bg--gradient {
background:fixed
}

.hp-heroBG {
background:url(https://img5.goodfon.com/wallpaper/nbig/5/35/peizazh-gory-neonovaia-luna-neonovaia-reka-neonovye-gory-neo.jpg);
background-size:100%
}

div.flash.flash--beta {
display:none
}

.structure.structure--flashed.structure--noAds {
padding-top:50px
}

.structure-ad {
display:none
}

.theme--pDefault .profile-bg {
background:url(https://i.redd.it/vwr7xn47pvk51.jpg) top left repeat,linear-gradient(0deg,#2d2e2e 60%,#fff 100%);
color:#d3d3d3;
background-size:100%
}

.theme--pDefault .profile-bgHead {
background:url(https://i.redd.it/vwr7xn47pvk51.jpg) top left repeat,linear-gradient(0deg,#2d2e2e 60%,#fff 100%);
background-size:100%
}

.theme--pDefault.is-gold .profile-bg {
background:url(https://static.vecteezy.com/system/resources/previews/001/849/609/non_2x/abstract-neon-background-free-vector.jpg) left bottom,linear-gradient(0deg,#d953fb 60%,#311bae 100%);
background-size:100%
}

.card--a {
background-color:#fff0;
color:#fff
}

.card--shadow-l {
box-shadow:none
}

.theme--pDefault .profile-levelNum {
color:#fff;
text-shadow:0 2px 2px #02020240
}

.theme--pDefault .profile-username {
text-shadow:0 0 7px #51bff2
}

.news--solo .news-body p {
color:#fff;
line-height:1.8
}

.news-teaser {
color:#fff;
margin-bottom:40px
}

.card--a {
color:#fff;
background:transparent;
text-shadow:0 0 7px #b42ff7
}

.card--shadow-l {
box-shadow:none
}

.btn--inky {
color:#fff
}

.card--b {
color:#fff
}

.theme--pDefault .profile-body {
color:#fff
}

.card--grit {
background:none
}

.dash-copyContainer {
background:#1d59d385;
box-shadow:0 1px 157px 10px #000000c7
}

.nav {
background:linear-gradient(to right,#303a42e3 0%,#2c3537d4 15%,#303a42e3 100%);
border-radius:5px;
border-top:1px solid #51bff2;
border-right:1px solid #51bff2;
border-bottom:1px solid #51bff2;
border-left:1px solid #51bff2;
height:100%;
width:100%
}

.nav-list-item.is-current {
background:radial-gradient(40px at 50% 100%,#ffffff26 0%,#fff0 100%),linear-gradient(to bottom,#20222e 30%,#20222e4d 100%);
border-top:1px solid #51bff2;
border-right:1px solid #51bff2;
border-bottom:1px solid #51bff2;
border-left:1px solid #51bff2;
box-shadow:inset 0 0 5px 0 #51bff2
}

.dash-copy {
color:#fff;
text-shadow:0 0 5px #ff00d9,0 0 7px #b42ff7;
font-family:"Roboto Mono","Courier New",Courier,"Lucida Sans Typewriter","Lucida Typewriter",monospace;
font-size:19px
}

.dash-letter.is-waiting {
background:#ae6aee;
color:#fff
}

.dash-letter.is-incorrect {
background:#e20b7bbd;
color:#fff
}

.btn--primary {
color:#fff;
background-size:100%;
background-color:#1f62802e!important;
border-color:#fff
}

.btn--secondary {
background-color:#0000!important;
color:#fff;
background-size:100%;
border-color:#fff
}

.card--team {
border:1px solid #e24adce8;
overflow:visible
}

.growl--a {
background-image:url(https://media.istockphoto.com/videos/4k-blue-pink-purple-neon-square-lights-purple-background-video-id1272936989?s=640x640);
border-color:#02020233;
background-size:150%;
color:#9d38ea
}

.growl-close {
background:#d751f2;
border-radius:50%;
border:1px solid #d751f2;
color:#fff;
padding:10px;
position:absolute;
right:-20px;
top:-5px;
transition:all .25s ease-in-out
}

.profile-carContainer.card.card--a.card--shadow-l {
background-color:#fff0
}

.raceResults-awards {
background:#fff0
}

.raceResults-close.raceResults-close--minimizer {
background:#ac51f2
}

.g.raceResults-grid {
background:#fff0
}

.dash-content {
background:url(https://i.redd.it/vwr7xn47pvk51.jpg);
background-size:100%
}

.raceResults-mini {
transform-origin:right bottom;
pointer-events:none;
opacity:0;
position:absolute;
padding:20px;
bottom:0;
left:50%;
transform:translate(-50%,200px);
border-radius:20px 20px 0 0;
background:linear-gradient(120deg,#2466f4 0%,#5524f4 30%,#ac51f2 70%,#d751f2 100%);
box-shadow:-10px 5px 10px 0 #02020233;
border-left:1px solid #1c99f499;
border-top:1px solid #3b3d4c;
z-index:1
}

.raceResults--default {
animation:colorchange1 30s linear 30s infinite;
-webkit-animation:colorchange1 30s linear 0s infinite alternate
}

@keyframes colorchange1 {
0% {
background-image:url(https://www.da-files.com/contests/2019/deviousdesktops/neon/gallery-12.jpg?8319445295);
background-size:100%
}

25% {
background-image:url(https://img.freepik.com/vetores-gratis/desenho-de-fundo-de-neon_52683-72514.jpg?size=626&ext=jpg);
background-size:100%
}

40% {
background-image:url(https://i.imgur.com/yMyksOx.jpg);
background-size:100%
}

55% {
background-image:url(https://img5.goodfon.com/wallpaper/nbig/5/35/peizazh-gory-neonovaia-luna-neonovaia-reka-neonovye-gory-neo.jpg);
background-size:100%
}

80% {
background-image:url(https://i.imgur.com/fcMs96d.jpg);
background-size:100%
}

100% {
background-image:url(https://i.redd.it/vwr7xn47pvk51.jpg);
background-size:100%
}
}

.structure-ad {
display:none
}

.card--season {
background:url(https://img5.goodfon.com/wallpaper/nbig/5/35/peizazh-gory-neonovaia-luna-neonovaia-reka-neonovye-gory-neo.jpg),linear-gradient(to bottom,#167ac3,#0e4d7a);
background-size:cover,auto,auto;
border-radius:30px;
padding:10px 20px;
color:#21b8d1;
opacity:100%
}

.footer-card {
background-image:url(https://i.pinimg.com/originals/1f/6f/ee/1f6feed025804ef1e3cda9fba5ffd914.jpg);
background-position:0 0;
background-repeat:no-repeat;
background-size:100%;
bottom:-30px;
padding:20px 20px 80px;
position:absolute;
right:15px;
transform:rotate(2deg);
width:300px;
z-index:2
}

.raceChat-pickerOptions {
background:linear-gradient(to bottom,#825ff3 30%,#bf57f3 100%);
border-radius:20px 0 0 20px;
display:none;
max-height:300px;
overflow-y:auto;
padding:0;
right:0;
width:auto;
z-index:2
}

.raceChat-pickerContainer {
background:linear-gradient(to bottom,#825ff3 30%,#bf57f3 100%);
border-radius:20px 0 0 20px;
bottom:70px;
display:none;
max-height:300px;
overflow-y:auto;
padding:15px;
position:absolute;
right:0;
z-index:2;
box-shadow:0 0 1px #10ede2,0 0 7px #00bfff
}

.raceChat-picker.is-toggled .raceChat-pickerToggle {
background:linear-gradient(to bottom,#bf57f3 30%,#825ff3 100%);
border-radius:0 0 50% 50%;
color:#fff;
height:70px
}

.footer-copyright {
background:#66ade733;
padding:20px;
position:relative;
width:100%;
z-index:1
}

.footer-nav {
background:url(https://c.neh.tw/thumb/f/720/9696f24b53034a369518.jpg);
background-repeat:no-repeat;
background-size:100%
}

.dropdown--account {
background:#ae6aeead;
border-radius:0 0 5px 5px;
font-size:14px;
padding:10px 15px;
color:#fff;
display:inline-block;
width:240px;
position:absolute;
top:0;
right:0
}

.dropdown--account .dropdown-items {
background:#3e1b49e3;
border-radius:0 0 5px 5px;
box-shadow:0 28px 28px 0 #0202020d,0 17px 17px 0 #02020233,0 8px 8px 0 #02020226;
width:240px
}

path:nth-child(7),path.logo-slash {
fill:#be1aeebd!important
}

.chart--a .chart-gradient .chart-gradient1 {
stop-color:#00bfff;
stop-opacity:.6
}

.chart--a .chart-gradient .chart-gradient2 {
stop-color:#b348d7;
stop-opacity:.3
}

.chart--a .chart-gradient .chart-gradient3 {
stop-color:#3d0867;
stop-opacity:.5
}

.raceResults-title--main,.raceResults-title--main:after {
color:#fff;
background:#b42ff7
}

.raceResults-title--place,.raceResults-title--place:after {
color:#b42ff7;
background:#fff;
font-style:italic
}

.chart--a .chart-line {
stroke:#0000!important;
stroke-width:2!important
}

.chart--a .chart-line circle {
fill:#000!important;
stroke-width:0!important;
stroke:#fff!important;
display:none
}

.card--e {
background:linear-gradient(145deg,#248d94c9 0%,#471182cf 30%,#292c3bd1 40%,#292c3bdb 41%,#292c3bd1 51%,#272a37cf 80%,#ae6aeead 100%),#1565af;
border:1px solid #3b3d4c;
color:#fff
}

.raceResults-rewards,.raceResults-dailyChallenges,.raceResults-userFeedback {
background:#486a7ead;
border-radius:5px;
padding:15px 20px;
position:relative
}

.achievement.is-complete .achievement-name {
color:#10ede2
}

.achievement.is-complete {
background:#3f324be3
}

::-webkit-scrollbar {
width:10px
}

::-webkit-scrollbar-track {
box-shadow:inset 0 0 5px #9f9c9c;
border-radius:10px
}

::-webkit-scrollbar-thumb {
background:#539ffb;
border-radius:10px
}

.profile-goldNotice {
background:#be1aeebd;
padding:10px 15px;
color:#ffffffcf;
font-weight:600;
font-size:14px;
line-height:1.33em;
border-radius:5px
}

.tc-brick {
color:#51bff2
}

.theme--pDefault .profile-ad {
border-color:#b42ff7
}

.link--nav {
color:#fff;
text-shadow:0 0 5px #ff00d9,0 0 7px #b42ff7;
font-weight:600;
font-size:14px;
line-height:1;
height:100%;
padding:0 0 5px;
transition:all .25s ease-in-out
}

.experiment {
height:auto;
width:100%;
background:linear-gradient(145deg,#248d94c9 0%,#272a37cf 30%,#292c3bd1 40%,#292c3bdb 41%,#292c3bd1 51%,#272a37cf 80%,#ae6aeead 100%),#3b3d4c;
z-index:1;
position:absolute;
border:5px solid #444;
box-sizing:border-box;
padding:7.5px 12.5px;
color:#fff;
text-shadow:0 0 5px #ff00d9,0 0 7px #b42ff7;
border-radius:2.5px
}

.dash .dash--tip {
background:#0d537391
}

.nmDash-message {
flex:0 0 auto;
border-radius:5px;
background:#9151f2de;
color:#fff;
text-shadow:0 0 1px #10ede2,0 0 7px #00bfff;
font-size:16px;
padding:15px 20px;
width:100%;
margin-bottom:10px;
box-shadow:0 28px 28px 0 #0202020d,0 17px 17px 0 #02020233,0 8px 8px 0 #02020226;
position:relative
}

.nmDash--race-mode {
background:#0d5373db;
display:flex;
flex-direction:column;
justify-content:center;
padding:0 20px;
height:80px;
border-radius:5px;
pointer-events:all;
line-height:1em;
gap:0;
z-index:1;
position:absolute!important;
left:20px;
top:35px;
cursor:default!important
}

.profile--active-car--car-name {
position:absolute;
top:100%;
left:50%;
background:#2466f485;
border-radius:5px;
padding:10px 20px;
color:#eee;
opacity:0
}

.page-shop--dealership-option.is-selected {
background:#095470d1;
box-shadow:none
}

.page-shop--dealership-option {
color:#fff;
background:#303a42e3;
margin:0 0 10px;
height:100px;
border-radius:5px 0 0 5px;
cursor:pointer;
box-shadow:0 0 3px #0202024d;
transition:all .2s;
transition-property:box-shadow,background;
display:flex;
align-items:center;
justify-content:center
}

.card--b {
color:#fff;
text-shadow:0 0 1px #10ede2,0 0 7px #00bfff
}

.dropdown--account .dropdown-link {
color:#fff;
text-shadow:0 0 1px #10ede2,0 0 7px #00bfff
}

.modal--error .modal-container {
background:linear-gradient(to bottom,#ac51f2 50%,#da51f2 95%,#fb53df 100%);
border-radius:20px;
border:6px solid #2466f4;
box-shadow:0 28px 28px 0 #0202020d,0 17px 17px 0 #02020233,0 8px 8px 0 #02020226
}

.btn--negative {
background:#00a7f5;
color:#d9e0f8;
text-shadow:0 0 1px #f053fb,0 0 7px #c300ff
}

.tc-ts {
color:#fff
}

.tc-i {
color:#fff;
text-shadow:0 0 1px #10ede2,0 0 7px #00bfff
}

.raceChat-pickerToggle {
align-items:center;
background:#fff;
border-radius:50%;
box-shadow:0 0 1px #10ede2,0 0 7px #00bfff;
color:#b42ff7;
display:flex;
height:70px;
justify-content:center;
outline:none;
position:relative;
width:70px;
z-index:1
}

.btn--tertiary {
background:#539ffb;
color:#d9f3ff;
text-shadow:0 0 1px #f053fb,0 0 7px #c300ff
}

::-moz-selection {
color:#fff;
background:#51bff2c7
}

::selection {
color:#fff;
background:#51bff2cf
}

.theme--pDefault .speedometer .speedometer-top {
color:#fff;
text-shadow:0 0 1px #10ede2,0 0 7px #00bfff
}

.ad {
display:none;
position:relative;
margin-right:auto;
margin-left:auto;
text-align:center
}

.ad--sq {
display:none;
width:336px;
height:280px;
background:#f2f2f2
}

.ad--ldrbrd {
display:none;
width:728px;
height:90px;
background:#f2f2f2
}

.ad--ldrbrd_l {
display:none;
width:970px;
height:90px
}

.ad--fixed {
display:none;
position:fixed;
top:30px
}

.theme--pDefault .profile-ad {
display:none
}

.bg--gradient2 {
background:url(https://i.redd.it/vwr7xn47pvk51.jpg) top left repeat,radial-gradient(circle at center right,#ffffff4d 0%,#ffffff1a 32%,#fff0 30%),linear-gradient(90deg,#c24eb0c2 60%,#17a7e7 100%)
}

.card.card--b.card--shadow.card--f.card--grit.well.well--b.well--l {
background:none;
background-color:#7a1197c7;
opacity:.94;
box-shadow:inset 0 20px 300px -20px #1ac5fca1
}

.btn--light {
background:#c3f1f8;
color:#b71dc0;
text-shadow:0 0 1px #10ede2,0 0 7px #00bfff
}

.racePanel--loading {
box-shadow:inset 0 -20px 20px 0 #000;
background:radial-gradient(circle closest-side at center center,#1c99f433 0%,#1c99f400) 5%,linear-gradient(to bottom,#15212d 0%,#532e7a 100%)
}

.notify {
align-items:center;
background:#de49f6;
border-radius:50%;
color:#fff;
display:flex;
font-size:10px;
font-weight:600;
height:18px;
justify-content:center;
position:absolute;
right:-11.7px;
top:-11.7px;
width:18px
}

.modal--gold-sale {
box-shadow:0 0 30px #43f0fa;
border-radius:20px;
color:#fff
}

.modal--a .modal-container {
background:none top left repeat,#ae56e921;
border-radius:20px;
box-shadow:0 1px 10px #020202
}

.mo dal--mysterybox .modal-container {
background:linear-gradient(to bottom,#f9d03400 75%,#34a9f9 100%) center center repeat-x,none center center repeat,none top left repeat,#20222e;
background-size:auto,65%,auto;
border-bottom:10px solid #167ac3;
border-radius:20px;
box-shadow:0 1px 10px #020202;
min-height:545px
}

.customizer--item-selector {
position:absolute;
right:10px;
top:90px;
bottom:10px;
z-index:1;
width:435px;
border:1px solid #584767f0;
border-radius:4px;
background:#584767f0
}

.section-paint .customizer--preview {
background:linear-gradient(0deg,#82359554 0%,#e0bb2f00 100%)
}

.modal--error .modal-container {
background:linear-gradient(to bottom,#2d74c2 4%,#5f1a8c 80%,#34063a 100%);
border-radius:20px;
border:2px solid #fff;
box-shadow:0 28px 28px 0 #0f255fff 0 17px 17px 0 #184050ff 0 8px 8px 0 #42a8cb63
}
}
